from fractions import Fraction as F
dist={1:F(1)}
for n in range(10):
    new={}
    for r,pr in dist.items():
        tot=n+2
        new[r+1]=new.get(r+1,0)+pr*F(r,tot)
        new[r]=new.get(r,0)+pr*F(tot-r,tot)
    dist=new
    assert sorted(dist)==list(range(1,n+3)) and all(v==F(1,n+2) for v in dist.values())

